using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogic_AllTargets", menuName = "Data/Battle/Logics/Dice Action/All Targets Dice")]
public class DiceActionLogic_AllTargets : DiceActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void ActionGrabbed()
	{
		base.ActionGrabbed();
		actionGameState.SetTargetOnActions(currentActiveUnits.GetCurrentActiveUnits());
	}
}
